return $input.all().map(item=>{
 const x=item.json;
 const leadId=String(x.leadId??"").trim();
 const fullName=String(x.fullName??"").trim().replace(/\s+/g," ");
 const email=String(x.email??"").trim().toLowerCase();
 const source=String(x.source??"").trim().toLowerCase();
 const errors=[];
 if(!leadId)errors.push("leadId_required");
 if(!fullName)errors.push("fullName_required");
 if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email))errors.push("email_invalid");
 return {json:{
   scenario:String(x.scenario??""),
   contractVersion:"1.0",
   valid:errors.length===0,
   errors,
   lead:{leadId,fullName,email,source},
   contractFields:["scenario","leadId","fullName","email","source"],
   component:"Normalize Lead Contract"
 }};
});
